2628:   drawPlant(px, py, slot, strain, p, index) {
2629:     const ctx = this.ctx;
2630:     if (!strain) return;
2631:     const prog = slot.progress;
2632:     const sway = Math.sin(this.time * 1.3 + index * 1.7) * .035;
2633:     const scale = .55 + prog * .55;
2634:     const stemH = 26 + prog * 40;
2635:     ctx.save();
2636:     ctx.translate(px, py - 2);
2637:     // stem
2638:     const topX = Math.sin(sway * 4) * 7, topY = -stemH;
2639:     ctx.strokeStyle = '#3f6e3f'; ctx.lineWidth = 2.1;
2640:     ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(2, -stemH * .55, topX, topY); ctx.stroke();
2641:     const nodes = prog < .35 ? 1 : prog < .7 ? 3 : 4;
2642:     for (let n = 0; n < nodes; n++) {
2643:       const t = (n + 1) / (nodes + .4);
2644:       const nx = topX * t * .7, ny = topY * t;
2645:       const dir = n % 2 ? 1 : -1;
2646:       const leafLen = (12 + prog * 12) * (1 - t * .25);
2647:       const ang = dir * (.7 + t * .2) + sway;
2648:       // stem branch
2649:       ctx.strokeStyle = '#4b7c48'; ctx.lineWidth = 1.4;
2650:       ctx.beginPath(); ctx.moveTo(nx, ny); ctx.quadraticCurveTo(nx + dir * leafLen * .5, ny - 4, nx + dir * leafLen, ny - 2); ctx.stroke();
2651:       // fan leaf shape
2652:       ctx.save(); ctx.translate(nx + dir * leafLen, ny - 2); ctx.rotate(ang);
2653:       ctx.fillStyle = n % 2 ? '#4f8a4a' : '#3f7340';
2654:       ctx.beginPath();
2655:       ctx.moveTo(0, 0);
2656:       ctx.bezierCurveTo(-6, -7, -15, -4, -18, 0);
2657:       ctx.bezierCurveTo(-13, 5, -5, 6, 0, 0);
2658:       ctx.fill();
2659:       ctx.strokeStyle = 'rgba(180,240,160,.25)'; ctx.lineWidth = .6;
2660:       for (let k = -2; k <= 2; k++) { ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-15, k * 2.4); ctx.stroke(); }
2661:       ctx.restore();
2662:     }
2663:     // buds
2664:     if (prog > .62) {
2665:       const density = prog > .95 ? 11 : 5 + Math.round(prog * 4);
2666:       const budR = (3.2 + prog * 4.8) * (1 + (slot.tendQ || 0) * .015);
2667:       const cols = [strain.color, shade(strain.color, -22), strain.accent];
2668:       for (let b = 0; b < density; b++) {
2669:         const t = .45 + seeded(b + index * 7.3) * .55;
2670:         const bx = topX * t + (seeded(b * 3.1 + index) - .5) * 24 * prog;
2671:         const by = topY * t + (seeded(b * 5.7 + index) - .5) * 13 * prog;
2672:         const r = budR * (.7 + seeded(b * 8.1) * .55);
2673:         ctx.fillStyle = cols[b % 3];
2674:         ctx.beginPath(); ctx.arc(bx, by, r, 0, TAU); ctx.fill();
2675:         ctx.fillStyle = 'rgba(255,255,255,.22)';
2676:         ctx.beginPath(); ctx.arc(bx - r * .25, by - r * .25, r * .35, 0, TAU); ctx.fill();
2677:         if (prog > .9) {
2678:           ctx.fillStyle = 'rgba(230,255,255,.6)';
2679:           for (let s = 0; s < 2; s++) { ctx.beginPath(); ctx.arc(bx + (seeded(b + s) - .5) * r * 1.4, by + (seeded(b + s * 2) - .5) * r, .7, 0, TAU); ctx.fill(); }
2680:         }
2681:       }
2682:       if (prog >= 1) {
2683:         const glow = ctx.createRadialGradient(0, topY * .8, 2, 0, topY * .8, 32 * scale);
2684:         glow.addColorStop(0, rgba(strain.color, .32)); glow.addColorStop(1, rgba(strain.color, 0));
2685:         ctx.fillStyle = glow;
2686:         ctx.beginPath(); ctx.arc(0, topY * .8, 32 * scale, 0, TAU); ctx.fill();
2687:       }
2688:     }
2689:     ctx.restore();
2690:   }
