2628:   drawPlant(px, py, slot, strain, p, index) {
2629:     const ctx = this.ctx;
2630:     if (!strain) return;
2631:     const prog = slot.progress;
2632:     const sway = Math.sin(this.time * 1.3 + index * 1.7) * .035;
2633:     const scale = .55 + prog * .55;
2634:     const stemH = 26 + prog * 40;
2635:     ctx.save();
2636:     ctx.translate(px, py - 2);
2637:     // stem
2638:     const topX = Math.sin(sway * 4) * 7, topY = -stemH;
2639:     ctx.strokeStyle = '#3f6e3f'; ctx.lineWidth = 2.1;
2640:     ctx.beginPath(); ctx.moveTo(0, 0); ctx.quadraticCurveTo(2, -stemH * .55, topX, topY); ctx.stroke();
2641:     const nodes = prog < .35 ? 1 : prog < .7 ? 3 : 4;
2642:     for (let n = 0; n < nodes; n++) {
2643:       const t = (n + 1) / (nodes + .4);
2644:       const nx = topX * t * .7, ny = topY * t;
2645:       const dir = n % 2 ? 1 : -1;
2646:       const leafLen = (12 + prog * 12) * (1 - t * .25);
2647:       const ang = dir * (.7 + t * .2) + sway;
