const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'networkidle' });
  for (const id of ['apartment', 'garage', 'lab', 'warehouse', 'empire']) {
    await page.evaluate(async (activeProperty) => {
      const { Game } = await import('/js/game.js');
      const { SAVE_KEY } = await import('/js/data.js');
      const game = new Game();
      const state = game.newState();
      state.activeProperty = activeProperty;
      state.dirty = 1e12; state.clean = 1e12;
      state.story.seen = true; state.story.idx = 20;
      for (const property of Object.values(state.properties)) property.owned = true;
      localStorage.setItem(SAVE_KEY, JSON.stringify(state));
    }, id);
    await page.reload({ waitUntil: 'networkidle' });
    await page.evaluate(() => {
      document.getElementById('splash')?.classList.add('hidden');
      document.getElementById('modalRoot')?.classList.add('hidden');
    });
    await page.waitForTimeout(500);
    await page.screenshot({ path: `/tmp/opencode/decor-${id}.jpg`, type: 'jpeg', quality: 72 });
    console.log(id, await page.locator('#scene').evaluate(c => [c.width, c.height]));
  }
  await browser.close();
})();
